const positions=['捕手','一塁手','二塁手','三塁手','遊撃手','左翼手','中堅手','右翼手','指名打者'];
const response=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store','Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'Content-Type','Access-Control-Allow-Methods':'GET,POST,OPTIONS'}});
const fail=(message,status=400)=>{throw Object.assign(Error(message),{status})},random=n=>crypto.getRandomValues(new Uint32Array(1))[0]%n,token=()=>Array.from(crypto.getRandomValues(new Uint8Array(24)),b=>b.toString(16).padStart(2,'0')).join(''),norm=s=>String(s||'').normalize('NFKC').replace(/\s+/g,''),songKey=s=>norm(s.name)+'#'+s.productionNumber;
let catalogCache=null,catalogAt=0;
async function catalog(){if(catalogCache&&Date.now()-catalogAt<60000)return catalogCache;const r=await fetch('https://ouenka-base-data.ninzin5600.workers.dev/songs',{signal:AbortSignal.timeout(15000)});if(!r.ok)fail('曲の一覧を取得できません。',502);const data=await r.json();if(!Array.isArray(data.songs))fail('曲の一覧を確認できません。',502);catalogCache=data.songs.map(s=>({name:String(s.player_name||s.name||'').slice(0,100),team:String(s.team||'').slice(0,100),productionNumber:String(s.production_number||s.productionNumber||1).slice(0,12),lyrics:String(s.lyrics||'').slice(0,4000),jerseyNumber:String(s.uniform_number??s.uniformNumber??'').slice(0,8)})).filter(s=>s.name);catalogAt=Date.now();return catalogCache}
function member(name,ai=false,slotCount=10){return {id:token().slice(0,16),token:ai?'':token(),name:String(name||'参加者').trim().slice(0,24)||'参加者',ai,roster:Array(slotCount).fill(null),nominations:[]}}
function turn(room){if(room.phase!=='draft')return null;const round=Math.floor(room.cursor/room.members.length),offset=room.cursor%room.members.length;return room.members[round%2?room.members.length-1-offset:offset]}
function select(room,m,key,slot,position){if(!Number.isInteger(slot)||slot<0||slot>=m.roster.length||m.roster[slot])fail('空いている打順を選んでください。');const song=room.pool.find(s=>songKey(s)===key);if(!song||room.used.includes(key))fail('その曲は指名済みです。');if(slot<9&&(!positions.includes(position)||m.roster.some(s=>s?.position===position)))fail('空いているポジションを選んでください。');if(m.roster.some(s=>s&&norm(s.name)===norm(song.name)))fail('同じ選手は1チームに1人です。');m.roster[slot]={...song,position:slot<9?position:m.roster.length===10?'投手':['先発','中継ぎ','抑え'][slot-9]};room.used.push(key);room.log.push({member:m.name,song:song.name,slot,position:m.roster[slot].position});room.cursor++;if(room.cursor===(room.slotCount||12)*room.members.length)room.phase='done'}
function advanceAI(room){for(let safety=0;safety<100;safety++){const m=turn(room);if(!m?.ai)return;const options=room.pool.filter(s=>!room.used.includes(songKey(s))&&!m.roster.some(p=>p&&norm(p.name)===norm(s.name)));if(!options.length)fail('候補が不足しています。');const preferred=options.filter(s=>s.team===m.favoriteTeam),song=(preferred.length?preferred:options)[random((preferred.length?preferred:options).length)],slot=m.roster.findIndex(s=>!s),position=positions.find(p=>!m.roster.some(s=>s?.position===p));select(room,m,songKey(song),slot,position)}}
function snapshot(room,me){return {code:room.code,revision:room.revision,phase:room.phase,hostId:room.hostId,me:me.id,expires:room.expires,slotCount:room.slotCount||12,cursor:room.cursor,turnId:turn(room)?.id||null,members:room.members.map(({token,...m})=>m),pool:room.pool,used:room.used,log:room.log}}
async function draftRoom(request,env){if(request.method==='OPTIONS')return response({ok:true});try{if(!env.BUCKET)fail('部屋サーバーを準備中です。',503);const url=new URL(request.url),action=url.pathname.split('/').pop();let body={};if(request.method==='POST'){if(Number(request.headers.get('content-length')||0)>120000)fail('データが大きすぎます。',413);const raw=await request.text();if(raw.length>120000)fail('データが大きすぎます。',413);try{body=JSON.parse(raw)}catch{fail('送信データを確認してください。')}}else if(request.method!=='GET')fail('未対応の操作です。',405);
if(action==='create'){if(request.method!=='POST')fail('POSTが必要です。',405);const aiCount=Number(body.aiCount||0);if(!Number.isInteger(aiCount)||aiCount<0||aiCount>7)fail('AIは0〜7人です。');const host=member(body.name),code=Array.from({length:8},()=> 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[random(32)]).join(''),room={code,revision:1,slotCount:10,phase:'lobby',hostId:host.id,expires:Date.now()+86400000,cursor:0,pool:[],used:[],log:[],members:[host,...Array.from({length:aiCount},(_,i)=>member('AI '+(i+1),true))]};const saved=await env.BUCKET.put('draft/'+code,JSON.stringify(room),{onlyIf:{etagDoesNotMatch:'*'}});if(!saved)fail('部屋を作り直してください。',409);return response({...snapshot(room,host),token:host.token})}
const code=String(body.code||url.searchParams.get('code')||'').toUpperCase();if(!/^[A-Z2-9]{8}$/.test(code))fail('部屋コードを確認してください。');const stored=await env.BUCKET.get('draft/'+code);if(!stored)fail('部屋が見つかりません。',404);const room=await stored.json();if(Date.now()>room.expires){await env.BUCKET.delete('draft/'+code);fail('部屋の有効期限が切れました。',410)}let me;
if(action==='join'){if(request.method!=='POST'||room.phase!=='lobby')fail('この部屋は参加受付を終了しています。',409);if(room.members.length>=8)fail('参加者はAIを含め8人までです。');me=member(body.name,false,room.slotCount||12);room.members.push(me)}else{const auth=String(body.token||request.headers.get('X-Draft-Token')||url.searchParams.get('token')||'');me=room.members.find(m=>!m.ai&&m.token===auth);if(!me)fail('参加情報を確認できません。',403)}
if(action==='state')return response(snapshot(room,me));if(request.method!=='POST')fail('POSTが必要です。',405);if(action!=='join'&&Number(body.revision)!==room.revision)fail('他の参加者が更新しました。最新表示でもう一度操作してください。',409);
if(action==='nominate'){if(room.phase!=='lobby')fail('候補曲の登録は終了しています。',409);if(!Array.isArray(body.keys)||body.keys.length<(room.slotCount||12)||body.keys.length>30)fail('候補曲を10〜30曲選んでください。');const all=await catalog(),keys=new Set(body.keys);me.nominations=all.filter(s=>keys.has(songKey(s)));if(new Set(me.nominations.map(s=>norm(s.name))).size!==body.keys.length)fail('同じ選手は1曲にして、登録された曲を選んでください。')}
else if(action==='start'){if(me.id!==room.hostId)fail('開始できるのは部屋の作成者です。',403);if(room.phase!=='lobby'||room.members.length<2)fail('参加者かAIを追加してください。');if(room.members.some(m=>!m.ai&&m.nominations.length<(room.slotCount||12)))fail('全員が必要数の候補を登録してください。');const all=await catalog(),pool=new Map();for(const m of room.members.filter(m=>!m.ai))for(const s of m.nominations)if(!pool.has(norm(s.name)))pool.set(norm(s.name),s);for(const m of room.members.filter(m=>m.ai)){const available=all.filter(s=>!pool.has(norm(s.name)));const picks=[];while(picks.length<(room.slotCount||12)&&available.length){const index=random(available.length),s=available.splice(index,1)[0];if(pool.has(norm(s.name)))continue;pool.set(norm(s.name),s);picks.push(s)}m.nominations=picks;m.favoriteTeam=picks[0]?.team||''}if(pool.size<(room.slotCount||12)*room.members.length)fail('重複を除いた候補が不足しています。1人あたりの候補を増やしてください。');room.pool=[...pool.values()];room.phase='draft';advanceAI(room)}
else if(action==='pass'){if(room.slotCount!==10||room.phase!=='draft'||turn(room)?.id!==me.id||!me.roster.slice(0,9).every(Boolean)||me.roster[9])fail('投手枠の指名時だけ省略できます。',409);room.cursor++;if(room.cursor===10*room.members.length)room.phase='done';advanceAI(room)}
else if(action==='pick'){if(room.phase!=='draft'||turn(room)?.id!==me.id)fail('今はあなたの指名順ではありません。',409);select(room,me,String(body.key),Number(body.slot),body.position);advanceAI(room)}
else if(action!=='join')fail('操作が見つかりません。',404);
room.revision++;const saved=await env.BUCKET.put('draft/'+code,JSON.stringify(room),{onlyIf:{etagMatches:stored.etag}});if(!saved)fail('同時に更新されました。再読み込みしてもう一度操作してください。',409);return response({...snapshot(room,me),...(action==='join'?{token:me.token}:{})});
}catch(e){return response({error:e.status?e.message:'通信に失敗しました。しばらくして再試行してください。'},e.status||500)}}



const json=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store','Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type'}});
async function popular(request,env){try{if(request.method==='OPTIONS')return json({ok:true});if(!env.BUCKET)return json({error:'ランキングを準備中です。'},503);const action=new URL(request.url).pathname.split('/').pop(),all=await catalog(),byKey=new Map(all.map(s=>[songKey(s),s]));if(action==='list'){if(request.method!=='GET')return json({error:'GETが必要です。'},405);const counts=new Map();let cursor,participants=0;do{const page=await env.BUCKET.list({prefix:'popular/',limit:200,cursor});const entries=await Promise.all(page.objects.map(async obj=>{const value=await env.BUCKET.get(obj.key);return value?value.json():null}));for(const entry of entries){if(!Array.isArray(entry?.keys))continue;participants++;for(const key of new Set(entry.keys))if(byKey.has(key))counts.set(key,(counts.get(key)||0)+1)}cursor=page.truncated?page.cursor:null}while(cursor);const songs=[...counts].map(([key,points])=>({...byKey.get(key),points})).sort((a,b)=>b.points-a.points||a.name.localeCompare(b.name,'ja'));let rank=0,prior=-1;for(let i=0;i<songs.length;i++){if(songs[i].points!==prior){rank=i+1;prior=songs[i].points}songs[i].rank=rank}return json({participants,songs,updatedAt:new Date().toISOString()})}
if(request.method!=='POST')return json({error:'POSTが必要です。'},405);const raw=await request.text();if(raw.length>120000)return json({error:'データが大きすぎます。'},413);const body=JSON.parse(raw);if(!/^[a-f0-9]{48}$/.test(String(body.id)))return json({error:'参加IDを確認してください。'},400);const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(body.id))),b=>b.toString(16).padStart(2,'0')).join(''),object='popular/'+hash;if(action==='mine'){const saved=await env.BUCKET.get(object),entry=saved?await saved.json():null;return json({songs:(entry?.keys||[]).filter(k=>byKey.has(k)).map(k=>byKey.get(k)),exists:!!entry})}if(action==='sync'){if(!Array.isArray(body.keys)||body.keys.length>2000)return json({error:'お気に入りは2000曲まで同期できます。'},400);const keys=[...new Set(body.keys)].filter(k=>byKey.has(k));await env.BUCKET.put(object,JSON.stringify({keys,updatedAt:Date.now()}));return json({ok:true,count:keys.length})}if(action==='leave'){await env.BUCKET.delete(object);return json({ok:true})}return json({error:'操作が見つかりません。'},404)}catch{return json({error:'集計に失敗しました。再試行してください。'},500)}}

const requestJson=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store','Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'Content-Type','Access-Control-Allow-Methods':'GET,POST,OPTIONS'}}),requestNorm=s=>String(s||'').normalize('NFKC').toLowerCase().replace(/\s+/g,''),requestHash=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))),b=>b.toString(16).padStart(2,'0')).join('');
const requestView=(entry,actor)=>({id:entry.id,name:entry.name,team:entry.team,kind:entry.kind,version:entry.version,note:entry.note,createdAt:entry.createdAt,status:entry.status,votes:entry.voters.length,voted:!!actor&&entry.voters.includes(actor)});
async function requests(request,env){try{if(request.method==='OPTIONS')return requestJson({ok:true});if(!env.BUCKET)return requestJson({error:'リクエスト箱を準備中です。'},503);let body={};if(request.method==='POST'){const raw=await request.text();if(raw.length>8000)return requestJson({error:'入力が長すぎます。'},413);try{body=JSON.parse(raw)}catch{return requestJson({error:'送信内容を確認してください。'},400)}}else if(request.method!=='GET')return requestJson({error:'未対応の操作です。'},405);const action=new URL(request.url).pathname.split('/').pop();let actor=null;if(body.identity){if(!/^[a-f0-9]{48}$/.test(String(body.identity)))return requestJson({error:'参加情報を確認してください。'},400);actor=await requestHash(body.identity)}
if(action==='list'){const entries=[];let cursor;do{const page=await env.BUCKET.list({prefix:'requests/',limit:100,cursor});const items=await Promise.all(page.objects.map(async obj=>{const stored=await env.BUCKET.get(obj.key);return stored?stored.json():null}));for(const entry of items)if(entry&&Array.isArray(entry.voters))entries.push(requestView(entry,actor));cursor=page.truncated?page.cursor:null}while(cursor);return requestJson({entries:entries.sort((a,b)=>b.votes-a.votes||b.createdAt-a.createdAt)})}
if(request.method!=='POST'||!actor)return requestJson({error:'参加情報を確認してください。'},400);
if(action==='create'){const fields={name:String(body.name||'').trim(),team:String(body.team||'').trim(),kind:String(body.kind||'個人応援歌'),version:String(body.version||'').trim(),note:String(body.note||'').trim()};if(!fields.name||fields.name.length>80||!fields.team||fields.team.length>100||fields.version.length>60||fields.note.length>600||!['個人応援歌','前奏','旧応援歌','汎用応援歌','データ修正'].includes(fields.kind))return requestJson({error:'選手・球団・種類を確認してください。補足は600文字以内です。'},400);const id=(await requestHash([fields.team,fields.name,fields.kind,fields.version].map(requestNorm).join('|'))).slice(0,32),key='requests/'+id,existing=await env.BUCKET.get(key);if(existing)return requestJson({entry:requestView(await existing.json(),actor),duplicate:true});const entry={...fields,id,author:actor,voters:[actor],createdAt:Date.now(),status:'募集中'},saved=await env.BUCKET.put(key,JSON.stringify(entry),{onlyIf:{etagDoesNotMatch:'*'}});if(!saved){const value=await env.BUCKET.get(key);if(value)return requestJson({entry:requestView(await value.json(),actor),duplicate:true});return requestJson({error:'同時に更新されました。再試行してください。'},409)}return requestJson({entry:requestView(entry,actor),duplicate:false})}
if(action==='vote'){if(!/^[a-f0-9]{32}$/.test(String(body.requestId))||typeof body.voted!=='boolean')return requestJson({error:'リクエストを確認してください。'},400);const key='requests/'+body.requestId;for(let attempt=0;attempt<3;attempt++){const old=await env.BUCKET.get(key);if(!old)return requestJson({error:'リクエストが見つかりません。'},404);const entry=await old.json(),set=new Set(entry.voters);if(body.voted)set.add(actor);else set.delete(actor);entry.voters=[...set];const saved=await env.BUCKET.put(key,JSON.stringify(entry),{onlyIf:{etagMatches:old.etag}});if(saved)return requestJson({entry:requestView(entry,actor)})}return requestJson({error:'同時に更新されています。再試行してください。'},409)}return requestJson({error:'操作が見つかりません。'},404)}catch{return requestJson({error:'通信に失敗しました。もう一度お試しください。'},500)}}

