export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname.startsWith('/api/draft/'))return draftRoom(request,env);if(url.pathname.startsWith('/api/popular/'))return popular(request,env);if(url.pathname.startsWith('/api/requests/'))return requests(request,env);let path;try{path=decodeURIComponent(url.pathname)}catch{return new Response('Bad request',{status:400})}if(path==='/')path='/index.html';const asset=assets[path];if(!asset)return new Response('Not found',{status:404});if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});return new Response(request.method==='HEAD'?null:Uint8Array.from(atob(asset[1]),c=>c.charCodeAt(0)),{headers:{'Content-Type':asset[0]+(asset[0].startsWith('text/')||asset[0].includes('javascript')||asset[0].includes('json')?'; charset=utf-8':''),'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}})}};
